import java.util.*;class Solution{public String alienOrder(String[]w){List<Integer>[]g=new List[26];for(int i=0;i<26;i++)g[i]=new ArrayList<>();int[]d=new int[26];boolean[]s=new boolean[26];for(String x:w)for(char c:x.toCharArray())s[c-'a']=true;for(int i=0;i+1<w.length;i++){int j=0,m=Math.min(w[i].length(),w[i+1].length());while(j<m&&w[i].charAt(j)==w[i+1].charAt(j))j++;if(j==m){if(w[i].length()>w[i+1].length())return"";}else{int a=w[i].charAt(j)-'a',b=w[i+1].charAt(j)-'a';if(!g[a].contains(b)){g[a].add(b);d[b]++;}}}Queue<Integer>q=new ArrayDeque<>();int cnt=0;for(int i=0;i<26;i++)if(s[i]){cnt++;if(d[i]==0)q.add(i);}StringBuilder r=new StringBuilder();while(!q.isEmpty()){int u=q.remove();r.append((char)('a'+u));for(int v:g[u])if(--d[v]==0)q.add(v);}return r.length()==cnt?r.toString():"";}}
